  /**
   * 绑定事件监听器
   */
  function bindEvents() {
    // 返回上步
    $('#prevBtn').on('click', function () {
      handlePreviousStep();
    });

    // 继续剧情
    $('#nextBtn').on('click', function () {
      handleNextStep();
    });

    // 当前剧情显示区域点击 - 直接打开剧情详情
    $('#currentStoryDisplay').on('click', function (e) {
      // 防止按钮点击事件冒泡（如回到当前剧情按钮）
      if ($(e.target).closest('button').length > 0) {
        return;
      }

      if (currentPlot !== '0' && currentPlot !== '' && stories.length > 0) {
        // 有当前剧情时，切换详情显示状态
        const $detailSection = $('#storyDetailSection');

        if ($detailSection.hasClass('show')) {
          // 如果详情已打开，则关闭
          hideStoryDetail();
        } else {
          // 如果详情未打开，则打开
          hideStoryList(); // 关闭剧情列表
          hideSettingsPanel(); // 关闭设置面板
          showStoryDetail(); // 打开详情
        }
      } else if (stories.length > 0) {
        // 未开始状态时，也打开剧情详情（如果有剧情数据）
        hideStoryList(); // 关闭剧情列表
        hideSettingsPanel(); // 关闭设置面板
        showStoryDetail(); // 打开详情
      } else {
        showFeedback('剧情数据加载中，请稍候...');
      }
    });

    // 剧情列表按钮
    $('#listBtn').on('click', function () {
      hideStoryDetail(); // 关闭剧情详情
      hideSettingsPanel(); // 关闭设置面板
      toggleStoryList();
    });

    // 设置按钮
    $('#settingsBtn').on('click', function () {
      hideStoryDetail(); // 关闭剧情详情
      hideStoryList(); // 关闭剧情列表
      toggleSettingsPanel();
    });

    // 关闭剧情列表
    $('#closeStoryListBtn').on('click', function () {
      hideStoryList();
    });

    // 排序按钮
    $('#sortBtn').on('click', function () {
      toggleSortOrder();
    });

    // 关闭剧情详情
    $('#closeDetailBtn').on('click', function () {
      hideStoryDetail();
    });

    // 关闭设置面板
    $('#closeSettingsBtn').on('click', function () {
      hideSettingsPanel();
    });

    // 返回剧情列表（从剧情详情）
    $('#backToMainBtn').on('click', function () {
      hideStoryDetail();
      hideSettingsPanel(); // 关闭设置面板
      showStoryList();
    });

    // 剧情列表项点击 - 直接打开剧情详情
    $(document).on('click', '.story-item', function () {
      try {
        const index = parseInt($(this).data('index'));
        console.log('🎬 点击剧情列表项，索引:', index, '对应剧情:', stories[index]?.title);

        if (isNaN(index) || index < 0 || index >= stories.length) {
          showFeedback(`无效的剧情索引: ${index}`);
          return;
        }

        currentStoryIndex = index;
        updateDisplay();
        hideStoryList();
        hideSettingsPanel(); // 关闭设置面板
        showStoryDetail();
      } catch (error) {
        console.error('剧情列表项点击错误:', error);
        showFeedback(`切换剧情时出错: ${error.message}`);
      }
    });

    // 回到当前剧情按钮
    $('#backToCurrentBtn').on('click', function (e) {
      e.stopPropagation(); // 阻止冒泡到父元素的点击事件
      backToCurrentPlot();
    });

    // 步骤执行按钮点击事件
    $(document).on('click', '.step-execute-btn', function (e) {
      e.stopPropagation(); // 阻止冒泡
      const stepId = $(this).attr('data-step-id'); // 使用attr()获取原始字符串值
      executeStep(stepId);
    });

    // 主题选择器事件监听
    $('#themeSelect').on('change', function () {
      const selectedTheme = $(this).val();
      applyTheme(selectedTheme);
      saveThemeSettings();

      // 根据主题显示不同的反馈消息
      const themeNames = {
        default: '🌅 晨曦蓝调主题',
        dark: '🌌 暗夜星辰主题',
        cute: '🌸 樱花粉梦主题',
        luxury: '✨ 琥珀奢华主题',
      };

      showFeedback(`已切换到 ${themeNames[selectedTheme] || selectedTheme}`);
    });

    // 执行策略选择器事件监听
    $('#executionStrategySelect').on('change', function () {
      const selectedStrategy = $(this).val();
      executionStrategy.mode = selectedStrategy;
      saveExecutionStrategySettings();

      // 根据策略显示不同的反馈消息
      const strategyNames = {
        direct: '⚡ 直接执行',
        copy: '📋 复制到酒馆对话框',
      };

      showFeedback(`已切换到 ${strategyNames[selectedStrategy] || selectedStrategy}`);
    });

    // 还原所有剧情按钮事件监听
    $('#resetAllPlotsBtn').on('click', function () {
      showResetConfirmation();
    });

    // 检测运行环境按钮事件监听
    $('#checkEnvironmentBtn').on('click', function () {
      checkEnvironment(true); // 手动检测，显示提示
    });
  }

  /**
   * 更新显示内容
   */
  function updateDisplay() {
    if (!stories || stories.length === 0) {
      // 显示数据加载失败状态
      showNoPlotState('数据加载中...', '请等待剧情数据加载');
      console.log('📋 显示数据加载状态：stories未准备好');
      return;
    }

    if (currentPlot === '0' || currentPlot === '') {
      // 显示未开始剧情状态 - 当数据源中currentPlot为空时
      showNoPlotState('未选择任何剧情', '点击此处选择剧情开始冒险');
      console.log('🎬 显示未选择剧情状态：currentPlot =', currentPlot);
      return;
    }

    if (currentStoryIndex < 0 || currentStoryIndex >= stories.length) {
      // 显示索引无效状态
      showNoPlotState('剧情索引无效', '请重新选择剧情');
      console.log('⚠️ 显示索引无效状态：currentStoryIndex =', currentStoryIndex);
      return;
    }

    // 恢复正常剧情显示状态
    showNormalPlotState();

    const currentStory = stories[currentStoryIndex];

    // 更新当前剧情信息
    $('#storyTitle').text(currentStory.title); // 新格式不需要移除序号前缀

    // 更新状态显示
    const currentStep = getCurrentStepInfo(currentStory, currentStory.currentStepId);
    const stepStatusIcon = currentStep?.isExecuted ? '✓' : '○';
    const stepStatusColor = currentStep?.isExecuted ? '#34C759' : '#FF9500';
    const stepStatusText = currentStep?.isExecuted ? '已执行' : '未执行';

    const statusHtml = `
      <div style="display: flex; align-items: center; gap: 8px; font-size: 14px;">
        <span style="color: ${stepStatusColor};">${stepStatusIcon} 步骤 ${
      currentStory.currentStepId
    } ${stepStatusText}</span>
        <span style="color: #8E8E93;">|</span>
        <span style="color: #007AFF;">共 ${currentStory.steps?.length || 0} 步</span>
      </div>
    `;
    $('#storyStatus').html(statusHtml);

    // 更新推进剧情显示
    updateProgressDisplay(currentStory);

    // 检查当前显示的剧情是否是数据源中的currentPlot
    const isAtDataSourceCurrentPlot = currentStory.id === currentPlot;
    if (isAtDataSourceCurrentPlot) {
      $('#backToCurrentBtn').hide();
      console.log('当前显示的是数据源currentPlot，隐藏回归按钮');
    } else {
      $('#backToCurrentBtn').show();
      console.log(`当前显示剧情ID ${currentStory.id}，数据源currentPlot是 ${currentPlot}，显示回归按钮`);
    }

    // 更新按钮状态
    updateButtonStates();
  }

  /**
   * 更新按钮状态
   */
  function updateButtonStates() {
    const currentStory = stories[currentStoryIndex];

    if (!currentStory || currentPlot === '0' || currentPlot === '') {
      // 未开始状态，禁用所有导航按钮
      $('#prevBtn').prop('disabled', true);
      $('#nextBtn').prop('disabled', true);
      return;
    }

    // 更新返回上步按钮状态
    const currentStepIdNum = parseInt(currentStepId);
    const canGoBack = currentStepIdNum > 1 || currentStoryIndex > 0;
    $('#prevBtn').prop('disabled', !canGoBack);

    // 更新继续剧情按钮状态
    const nextStep = getNextStep(currentStory);
    const hasNextStep = nextStep !== null;
    const hasNextStory = currentStoryIndex < stories.length - 1;
    const canGoForward = hasNextStep || hasNextStory;
    $('#nextBtn').prop('disabled', !canGoForward);

    // 调试信息
    console.log('🔘 按钮状态更新：', {
      currentPlot: currentPlot,
      currentStepId: currentStepId,
      currentStepIdNum: currentStepIdNum,
      currentStoryIndex: currentStoryIndex,
      canGoBack: canGoBack,
      canGoForward: canGoForward,
      hasNextStep: hasNextStep,
      hasNextStory: hasNextStory,
      prevBtnDisabled: $('#prevBtn').prop('disabled'),
      nextBtnDisabled: $('#nextBtn').prop('disabled'),
    });
  }

  /**
   * 显示未开始剧情状态
   */
  function showNoPlotState(title, hint) {
    console.log('🎭 执行showNoPlotState：', title, hint);

    // 添加特殊样式类
    const $display = $('#currentStoryDisplay');
    $display.addClass('no-plot');
    console.log('添加no-plot样式类到元素：', $display.length > 0 ? '成功' : '失败');

    // 显示图标和文本
    const $icon = $('#noPlotIcon');
    $icon.show();
    console.log('显示noPlotIcon：', $icon.length > 0 ? '成功' : '失败');

    $('#storyTitle').text(title);
    $('#storyStatus').text('');

    // 隐藏回到当前剧情按钮
    $('#backToCurrentBtn').hide();

    // 禁用导航按钮
    $('#prevBtn').prop('disabled', true);
    $('#nextBtn').prop('disabled', true);

    console.log('✅ 未开始剧情状态显示完成：', title);
  }

  /**
   * 恢复正常剧情显示状态
   */
  function showNormalPlotState() {
    console.log('🔄 恢复正常剧情显示状态');

    // 移除特殊样式类
    const $display = $('#currentStoryDisplay');
    $display.removeClass('no-plot');
    console.log('移除no-plot样式类：', $display.hasClass('no-plot') ? '失败' : '成功');

    // 隐藏未开始状态图标
    const $icon = $('#noPlotIcon');
    $icon.hide();
    console.log('隐藏noPlotIcon：', $icon.is(':visible') ? '失败' : '成功');

    console.log('✅ 正常剧情显示状态恢复完成');
  }

  /**
   * 显示/隐藏剧情列表
   */
  function toggleStoryList() {
    const $section = $('#storyListSection');

    if ($section.is(':visible')) {
      hideStoryList();
    } else {
      showStoryList();
    }
  }

  /**
   * 显示剧情列表
   */
  function showStoryList() {
    const $section = $('#storyListSection');
    const $listContainer = $('#storyListContainer');

    // 清空并重新构建列表
    $listContainer.empty();

    stories.forEach((story, index) => {
      // 计算已执行步骤数
      const executedStepsCount = story.steps.filter(step => step.isExecuted).length;
      const totalStepsCount = story.steps.length;
      const isCurrentPlot = String(story.id) === String(currentPlot);

      const $item = $(`
        <div class="story-item ${isCurrentPlot ? 'current' : ''}" data-index="${index}">
          <div class="story-item-content">
            <div class="story-item-title">${story.title}</div>
            <div class="story-item-progress">${executedStepsCount}/${totalStepsCount} 步骤</div>
          </div>
        </div>
      `);
      $listContainer.append($item);
    });

    // 立即显示，无动画
    $section.show().addClass('show').css({
      transition: 'none',
      transform: 'translateY(0) scaleY(1)',
      opacity: '1',
    });

    // 自动滚动到当前剧情（currentPlot.uniqueID）
    setTimeout(() => {
      const currentPlotIndex = stories.findIndex(story => story.id === currentPlot);
      if (currentPlotIndex !== -1) {
        const $currentItem = $listContainer.find(`.story-item[data-index="${currentPlotIndex}"]`);
        if ($currentItem.length > 0) {
          // 使用 scrollIntoView 滚动到当前剧情
          $currentItem[0].scrollIntoView({
            behavior: 'smooth',
            block: 'center',
          });
          console.log('✅ 自动滚动到当前剧情：', stories[currentPlotIndex].title);
        }
      }
    }, 350); // 等待弹出动画完成后再滚动

    // 展开插件
    if (typeof window.expandPlugin === 'function') {
      window.expandPlugin();
    }

    // 额外通知高度变化（确保iframe正确调整）
    setTimeout(() => {
      if (typeof window.notifyParentHeightChange === 'function') {
        window.notifyParentHeightChange();
      }
    }, 100);

    // 再次通知（防止初次计算不准确）
    setTimeout(() => {
      if (typeof window.notifyParentHeightChange === 'function') {
        window.notifyParentHeightChange();
      }
    }, 400);

    // 滚动到顶部
    scrollToTop();
  }

  /**
   * 隐藏剧情列表
   */
  function hideStoryList() {
    const $section = $('#storyListSection');
    $section.removeClass('show');
    setTimeout(() => {
      $section.hide();
    }, 300);

    // 收缩插件
    if (typeof window.collapsePlugin === 'function') {
      window.collapsePlugin();
    }
  }

  /**
   * 切换排序顺序
   */
  function toggleSortOrder() {
    sortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
    sortStories();
    updateSortButton();
    showStoryList(); // 重新显示列表
    showFeedback(`已按序号${sortOrder === 'asc' ? '正向' : '反向'}排序`);
  }

  /**
   * 对剧情进行排序
   */
  function sortStories() {
    const currentStoryId = stories[currentStoryIndex]?.id;

    stories.sort((a, b) => {
      if (sortOrder === 'asc') {
        return a.id - b.id;
      } else {
        return b.id - a.id;
      }
    });

    // 重新找到当前剧情的索引
    if (currentStoryId) {
      const newIndex = stories.findIndex(story => story.id === currentStoryId);
      if (newIndex !== -1) {
        currentStoryIndex = newIndex;
      }
    }

    updateDisplay();
  }

  /**
   * 更新排序按钮显示
   */
  function updateSortButton() {
    const $sortBtn = $('#sortBtn');
    $sortBtn.removeClass('asc desc').addClass(sortOrder);

    if (sortOrder === 'asc') {
      $sortBtn.find('.btn-icon').text('↑');
      $sortBtn.attr('title', '当前正向排序，点击反向排序');
    } else {
      $sortBtn.find('.btn-icon').text('↓');
      $sortBtn.attr('title', '当前反向排序，点击正向排序');
    }
  }

  /**
   * 获取当前步骤信息
   */
  function getCurrentStepInfo(story, stepId) {
    if (!story || !story.steps) return null;
    // 使用 == 进行比较，允许字符串和数字的比较
    return story.steps.find(step => step.stepId == stepId) || story.steps[0];
  }

  /**
   * 更新推进剧情显示
   */
  function updateProgressDisplay(currentStory) {
    const $progressDisplay = $('#storyProgress');

    if (!currentStory || !currentStory.steps) {
      $progressDisplay.hide();
      return;
    }

    // 查找当前剧情的下一个未执行步骤
    const nextStep = getNextStep(currentStory);

    if (nextStep) {
      // 当前剧情还有未执行步骤
      const progressText = `推进剧情: 步骤 ${nextStep.stepId} - ${nextStep.event || '未指定'}`;
      $progressDisplay.text(progressText).show();
    } else {
      // 当前剧情已完成，查找下一个剧情的第一个步骤
      const nextStoryStep = getNextStoryFirstStep();
      if (nextStoryStep) {
        const progressText = `推进剧情: 下一剧情 - ${nextStoryStep.event || '未指定'}`;
        $progressDisplay.text(progressText).show();
      } else {
        // 已经是最后一个剧情且已完成
        $progressDisplay.text('推进剧情: 所有剧情已完成').show();
      }
    }
  }

  /**
   * 获取当前剧情的下一个未执行步骤
   */
  function getNextStep(story) {
    if (!story || !story.steps) return null;

    // 查找第一个未执行的步骤
    return story.steps.find(step => !step.isExecuted);
  }

  /**
   * 获取下一个剧情的第一个步骤
   */
  function getNextStoryFirstStep() {
    if (currentStoryIndex >= stories.length - 1) return null;

    const nextStory = stories[currentStoryIndex + 1];
    if (!nextStory || !nextStory.steps || nextStory.steps.length === 0) return null;

    return nextStory.steps[0];
  }

  /**
   * 处理返回上步操作
   */
  async function handlePreviousStep() {
    const currentStory = stories[currentStoryIndex];
    if (!currentStory) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 使用当前步骤ID进行计算（stepId - 1）
    const currentStepIdNum = parseInt(currentStepId);

    if (currentStepIdNum > 1) {
      // 当前步骤ID大于1，返回到上一个步骤
      const previousStepId = (currentStepIdNum - 1).toString();

      // 检查上一个步骤是否存在（使用 == 允许字符串和数字比较）
      const prevStep = currentStory.steps.find(step => step.stepId == previousStepId);
      if (prevStep) {
        currentStepId = previousStepId;
        currentStory.currentStepId = previousStepId;

        // 在生产环境中保存状态
        await saveCurrentPlotToWorldbook();

        updateDisplay();
        showFeedback(`已返回到步骤 ${previousStepId}`);
      } else {
        showFeedback(`步骤 ${previousStepId} 不存在`);
      }
    } else {
      // 当前步骤ID为1，返回到上一个剧情的最后一个步骤
      if (currentStoryIndex > 0) {
        currentStoryIndex--;
        const prevStory = stories[currentStoryIndex];
        if (prevStory.steps && prevStory.steps.length > 0) {
          // 找到上一个剧情的最后一个步骤
          const lastStep = prevStory.steps[prevStory.steps.length - 1];
          currentPlot = prevStory.id;
          currentStepId = lastStep.stepId;
          prevStory.currentStepId = lastStep.stepId;

          // 在生产环境中保存状态
          await saveCurrentPlotToWorldbook();

          updateDisplay();
          showFeedback(`已返回到上一个剧情的最后步骤：${lastStep.stepId}`);
        } else {
          showFeedback('上一个剧情没有可用步骤');
        }
      } else {
        showFeedback('已经是第一个剧情的第一个步骤了');
      }
    }
  }

  /**
   * 处理继续剧情操作
   */
  async function handleNextStep() {
    const currentStory = stories[currentStoryIndex];
    if (!currentStory) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 查找当前剧情的下一个未执行步骤
    const nextStep = getNextStep(currentStory);

    if (nextStep) {
      // 当前剧情还有未执行步骤，执行该步骤
      executeStep(nextStep.stepId);
    } else {
      // 当前剧情已完成，前进到下一个剧情的第一个步骤
      if (currentStoryIndex < stories.length - 1) {
        currentStoryIndex++;
        const nextStory = stories[currentStoryIndex];
        if (nextStory.steps && nextStory.steps.length > 0) {
          // 更新当前剧情和步骤ID
          currentPlot = nextStory.id;
          currentStepId = nextStory.steps[0].stepId;
          nextStory.currentStepId = nextStory.steps[0].stepId;

          // 自动执行下一个剧情的第一步
          console.log('🎬 自动前进到下一个剧情并执行第一步:', nextStory.title);
          await executeStep(nextStory.steps[0].stepId);

          hideStoryList(); // 关闭剧情列表
        } else {
          showFeedback('下一个剧情没有可用步骤');
        }
      } else {
        showFeedback('已经是最后一个剧情了');
      }
    }
  }

  /**
   * 更新当前剧情ID - 仅用于导航时同步显示
   * 注意：这里只是同步显示，不改变数据源中的currentPlot
   */
  function updateCurrentPlot() {
    // 这个函数仅用于导航时的显示同步，不应该修改原始的currentPlot
    // 原始的currentPlot来自数据源，应该保持不变直到真正执行剧情
    console.log(
      '导航显示更新：当前显示剧情ID',
      stories[currentStoryIndex]?.id,
      '数据源currentPlot:',
      currentPlot,
      'stepId:',
      currentStepId,
    );
  }

  /**
   * 回到数据源中的当前剧情
   */
  function backToCurrentPlot() {
    if (!stories || stories.length === 0) {
      showFeedback('没有可用的剧情数据');
      return;
    }

    if (currentPlot === '0' || currentPlot === '') {
      showFeedback('数据源中未设置当前剧情');
      return;
    }

    // 查找数据源中currentPlot对应的剧情索引
    const targetIndex = stories.findIndex(story => String(story.id) === String(currentPlot));

    if (targetIndex === -1) {
      showFeedback(`找不到剧情ID ${currentPlot}，请检查数据源`);
      console.error(
        '找不到当前剧情：',
        currentPlot,
        '可用剧情：',
        stories.map(s => s.id),
      );
      return;
    }

    // 切换到目标剧情
    const previousIndex = currentStoryIndex;
    currentStoryIndex = targetIndex;
    updateDisplay();

    // 关闭可能打开的面板
    hideStoryList();
    hideSettingsPanel();

    // 打开当前剧情的详情页
    showStoryDetail();

    // 提供详细的反馈信息
    const currentStory = stories[currentStoryIndex];
