/**
 * 剧情小助手 - 主要逻辑控制
 * Story Assistant - Main Logic Controller
 */

$(document).ready(function () {
  // 环境配置
  let isDev = false; // 开发环境标识，打包时会自动改为 false

  // 初始化剧情数据
  let stories = [];
  let currentStoryIndex = 0;
  let currentPlot = '0'; // 来自数据源的currentPlot (现在是uniqueID)
  let currentStepId = '1'; // 来自数据源的当前步骤ID
  let sortOrder = 'asc'; // 排序顺序：'asc' 或 'desc'

  // 主题设置
  let themeSettings = {
    currentTheme: 'default', // 当前主题: default, cute, dark
  };

  // 执行剧情策略设置
  let executionStrategy = {
    mode: 'direct', // 'direct' - 直接执行, 'copy' - 复制到酒馆对话框
  };

  /**
   * 初始化插件
   */
  async function initStoryAssistant() {
    loadThemeSettings(); // 加载主题设置
    loadExecutionStrategySettings(); // 加载执行策略设置
    bindEvents();
    await loadStoryData(); // 异步加载数据，数据加载完成后会自动调用updateDisplay()
  }

  /**
   * 加载主题设置
   */
  function loadThemeSettings() {
    try {
      const saved = localStorage.getItem('storyAssistant_themeSettings');
      if (saved) {
        const settings = JSON.parse(saved);
        themeSettings = { ...themeSettings, ...settings };
      }

      // 应用保存的主题
      applyTheme(themeSettings.currentTheme);
    } catch (error) {
      console.warn('加载主题设置失败:', error);
      // 使用默认主题
      applyTheme('default');
    }
  }

  /**
   * 保存主题设置
   */
  function saveThemeSettings() {
    try {
      localStorage.setItem('storyAssistant_themeSettings', JSON.stringify(themeSettings));
    } catch (error) {
      console.warn('保存主题设置失败:', error);
    }
  }

  /**
   * 加载执行策略设置
   */
  function loadExecutionStrategySettings() {
    try {
      const saved = localStorage.getItem('storyAssistant_executionStrategy');
      if (saved) {
        const settings = JSON.parse(saved);
        executionStrategy = { ...executionStrategy, ...settings };
      }

      console.log('✅ 执行策略设置已加载:', executionStrategy.mode);
    } catch (error) {
      console.warn('加载执行策略设置失败:', error);
      // 使用默认策略
      executionStrategy.mode = 'direct';
    }
  }

  /**
   * 保存执行策略设置
   */
  function saveExecutionStrategySettings() {
    try {
      localStorage.setItem('storyAssistant_executionStrategy', JSON.stringify(executionStrategy));
      console.log('💾 执行策略设置已保存:', executionStrategy.mode);
    } catch (error) {
      console.warn('保存执行策略设置失败:', error);
    }
  }

  /**
   * 应用主题
   */
  function applyTheme(themeName) {
    const body = document.body;

    // 移除之前的主题类
    body.removeAttribute('data-theme');

    // 应用新主题
    if (themeName !== 'default') {
      body.setAttribute('data-theme', themeName);
    }

    // 更新设置
    themeSettings.currentTheme = themeName;

    console.log('✨ 主题已切换至:', themeName);

    // 触发主题变化动画
    const container = document.querySelector('.story-assistant-container');
    if (container) {
      container.style.transform = 'scale(0.98)';
      setTimeout(() => {
        container.style.transform = '';
      }, 200);
    }
  }

  /**
   * 加载剧情数据
   */
  async function loadStoryData() {
    if (isDev) {
      // 开发环境：从 new-plot-data.json 文件读取数据
      console.log('🔧 开发环境：从 new-plot-data.json 加载剧情数据');
      $.getJSON('data/new-plot-data.json')
        .done(function (data) {
          console.log('✅ 开发环境：成功加载外部数据文件');
          console.log('📊 开发环境：currentPlot =', data.currentPlot);
          processPlotData(data);
        })
        .fail(function (jqxhr, textStatus, error) {
          console.error('❌ 开发环境：加载剧情数据失败:', textStatus, error);
          // 回退到默认数据
          loadDefaultData();
        });
    } else {
      // 生产环境：处理剧情数据
      console.log('🚀 生产环境：处理剧情数据');

      // 调用生产环境处理函数
      await processPlotDataForProduction();
    }
  }

  /**
   * 处理剧情数据（开发环境）
   */
  function processPlotData(data) {
    // 处理新格式的数据结构
    const plotList = data.plotList || [];

    // 转换为标准格式 - 每个剧情包含其所有步骤
    stories = plotList.map((plot, index) => {
      // 使用索引作为ID（因为新格式没有uniqueID）
      const plotId = index + 1;

      // 找到当前执行的步骤
      const currentStep = plot.steps?.find(step => step.isExecuted) || plot.steps?.[0] || {};

      return {
        id: plotId, // 使用索引+1作为ID
        title: plot.title,
        summary: plot.summary || '', // 新增：剧情摘要
        content: currentStep.event || '', // 当前步骤的事件作为内容
        steps: plot.steps || [],
        currentStepId: currentStep.stepId || '1',
        isExecuted: plot.steps?.some(step => step.isExecuted) || false,
      };
    });

    // 按ID排序
    stories.sort((a, b) => parseInt(a.id) - parseInt(b.id));

    // 设置currentPlot（来自数据源）
    const currentPlotData = data.currentPlot || {};
    currentPlot = currentPlotData.plotId ? String(currentPlotData.plotId) : '0'; // 新格式：plotId
    currentStepId = currentPlotData.stepId ? String(currentPlotData.stepId) : '1';

    console.log('📊 数据源currentPlot设置为：', currentPlot, 'stepId:', currentStepId);

    // 根据currentPlot设置当前剧情索引
    if (currentPlot !== '0') {
      const foundIndex = stories.findIndex(story => String(story.id) === String(currentPlot));
      if (foundIndex !== -1) {
        currentStoryIndex = foundIndex;
        // 同步当前剧情的currentStepId
        const currentStory = stories[currentStoryIndex];
        if (currentStory) {
          currentStory.currentStepId = currentStepId;
        }
        console.log(`✅ 找到数据源currentPlot ${currentPlot}，对应索引 ${foundIndex}，同步stepId: ${currentStepId}`);
      } else {
        currentStoryIndex = 0;
        console.warn(`⚠️ 数据源currentPlot ${currentPlot} 在剧情列表中未找到，使用索引 0`);
      }
    } else {
      currentStoryIndex = 0;
      console.log('🎭 数据源currentPlot为空，表示未开始任何剧情，即将调用updateDisplay显示未选择状态');
    }

    updateDisplay();
    updateSortButton(); // 初始化排序按钮状态
    console.log('🎬 剧情数据加载完成：');
    console.log('   - 总剧情数：', stories.length);
    console.log('   - 数据源currentPlot：', currentPlot);
    console.log('   - 当前stepId：', currentStepId);
    console.log('   - 初始显示索引：', currentStoryIndex);
    console.log('   - 初始显示剧情：', stories[currentStoryIndex]?.title || '无');
  }

  /**
   * 处理剧情数据（生产环境）
   */
  async function processPlotDataForProduction() {
    console.log('🏭 生产环境：处理剧情数据');

    // 检查是否有内联数据（构建后的版本）
    if (typeof window.plot_data !== 'undefined') {
      console.log('✅ 生产环境：使用内联数据');
      processPlotData(window.plot_data);
      // 成功加载，停止重试机制
      stopRetryMechanism();
      return;
    }

    // 尝试从世界书获取数据
    if (typeof window.initProductionEnvironment === 'function') {
      console.log('🔍 生产环境：尝试从世界书获取剧情数据');

      try {
        const result = await window.initProductionEnvironment();

        if (result.success && result.data) {
          console.log('✅ 生产环境：成功从世界书获取数据');
          processPlotData(result.data);
          // 成功加载，停止重试机制
          stopRetryMechanism();
          showFeedback('✅ 数据加载成功！');
        } else {
          console.error('❌ 生产环境：世界书数据获取失败:', result.error);
          // 只有在首次加载时才显示错误（避免重试时重复显示）
          if (retryCount === 0) {
            showProductionError('世界书数据获取失败', result.error);
          } else {
            // 重试失败，继续下一次重试
            throw new Error(result.error);
          }
        }
      } catch (error) {
        console.error('💥 生产环境：初始化过程出错:', error);
        // 只有在首次加载时才显示错误（避免重试时重复显示）
        if (retryCount === 0) {
          showProductionError('生产环境初始化失败', error.message);
        } else {
          // 重试失败，继续下一次重试
          throw error;
        }
      }
    } else {
      console.warn('⚠️ 生产环境：initProductionEnvironment 函数不可用');
      // 只有在首次加载时才显示错误（避免重试时重复显示）
      if (retryCount === 0) {
        showProductionError('生产环境配置错误', 'initProductionEnvironment 函数不可用，可能未正确加载 init.js');
      } else {
        // 重试失败，继续下一次重试
        throw new Error('initProductionEnvironment 函数不可用');
      }
    }
  }

  /**
   * 显示生产环境错误
   */
  function showProductionError(title, message) {
    console.error('🚨 生产环境错误:', title, '-', message);

    // 显示错误状态
    showNoPlotState(`生产环境错误: ${title}`, `生产环境数据加载失败，请检查世界书配置`);

    // 显示持久错误消息
    const fullErrorMsg = `🚨 生产环境错误\n\n标题: ${title}\n详情: ${message}\n\n请检查：\n1. 是否有名为"剧情元数据-By萧谴剧情模拟器"的世界书条目\n2. 条目内容是否为有效的JSON格式\n3. JSON数据是否包含 currentPlot 和 plotList 字段`;

    showFeedback(fullErrorMsg);

    // 启动重试机制：每隔5秒重试一次，连续重试3次
    startRetryMechanism();
  }

  /**
   * 重试机制：每隔5秒重试一次，连续重试3次
   */
  let retryCount = 0;
  let retryTimer = null;
  const MAX_RETRY_COUNT = 3;
  const RETRY_INTERVAL = 5000; // 5秒

  function startRetryMechanism() {
    // 清除之前的重试定时器（如果存在）
    if (retryTimer) {
      clearTimeout(retryTimer);
    }

    retryCount = 0;
    console.log('🔄 启动重试机制：将每隔5秒重试一次，最多重试3次');

    // 启动第一次重试
    scheduleRetry();
  }

  function scheduleRetry() {
    if (retryCount >= MAX_RETRY_COUNT) {
      console.error('❌ 已达到最大重试次数，停止重试');
      showFeedback(`已重试 ${MAX_RETRY_COUNT} 次，仍无法加载数据。请检查世界书配置。`);
      return;
    }

    retryCount++;
    console.log(`⏰ 准备第 ${retryCount} 次重试，将在 ${RETRY_INTERVAL / 1000} 秒后执行...`);

    showFeedback(`第 ${retryCount} 次重试将在 ${RETRY_INTERVAL / 1000} 秒后开始...`);

    retryTimer = setTimeout(async () => {
      console.log(`🔄 执行第 ${retryCount} 次重试...`);
      showFeedback(`正在执行第 ${retryCount} 次重试...`);

      try {
        // 重新尝试加载数据
        await processPlotDataForProduction();
      } catch (error) {
        console.error(`❌ 第 ${retryCount} 次重试失败:`, error);

        // 如果还有重试次数，继续重试
        if (retryCount < MAX_RETRY_COUNT) {
          scheduleRetry();
        } else {
          console.error('❌ 已达到最大重试次数，停止重试');
          showFeedback(`已重试 ${MAX_RETRY_COUNT} 次，仍无法加载数据。请检查世界书配置。`);
        }
      }
    }, RETRY_INTERVAL);
  }

  /**
   * 停止重试机制
   */
  function stopRetryMechanism() {
    if (retryTimer) {
      clearTimeout(retryTimer);
      retryTimer = null;
    }
    retryCount = 0;
    console.log('⏹️ 重试机制已停止');
  }

  /**
   * 加载默认数据（备用）
   */
  function loadDefaultData() {
    stories = [
      {
        id: 1,
        title: '1. 数据加载失败',
        content: '无法在生产环境中加载数据文件，请检查文件路径和格式。',
        description: '数据加载错误',
        location: '系统',
        participants: ['系统'],
        cause: '文件加载失败',
        ending: '显示错误信息',
        isExecuted: false,
      },
    ];

    updateDisplay();
    console.log('使用默认数据');
  }

  /**
   * 绑定事件监听器
   */
  function bindEvents() {
    // 返回上步
    $('#prevBtn').on('click', function () {
      handlePreviousStep();
    });

    // 继续剧情
    $('#nextBtn').on('click', function () {
      handleNextStep();
    });

    // 当前剧情显示区域点击 - 直接打开剧情详情
    $('#currentStoryDisplay').on('click', function (e) {
      // 防止按钮点击事件冒泡（如回到当前剧情按钮）
      if ($(e.target).closest('button').length > 0) {
        return;
      }

      if (currentPlot !== '0' && currentPlot !== '' && stories.length > 0) {
        // 有当前剧情时，切换详情显示状态
        const $detailSection = $('#storyDetailSection');

        if ($detailSection.hasClass('show')) {
          // 如果详情已打开，则关闭
          hideStoryDetail();
        } else {
          // 如果详情未打开，则打开
          hideStoryList(); // 关闭剧情列表
          hideSettingsPanel(); // 关闭设置面板
          showStoryDetail(); // 打开详情
        }
      } else if (stories.length > 0) {
        // 未开始状态时，也打开剧情详情（如果有剧情数据）
        hideStoryList(); // 关闭剧情列表
        hideSettingsPanel(); // 关闭设置面板
        showStoryDetail(); // 打开详情
      } else {
        showFeedback('剧情数据加载中，请稍候...');
      }
    });

    // 剧情列表按钮
    $('#listBtn').on('click', function () {
      hideStoryDetail(); // 关闭剧情详情
      hideSettingsPanel(); // 关闭设置面板
      toggleStoryList();
    });

    // 设置按钮
    $('#settingsBtn').on('click', function () {
      hideStoryDetail(); // 关闭剧情详情
      hideStoryList(); // 关闭剧情列表
      toggleSettingsPanel();
    });

    // 关闭剧情列表
    $('#closeStoryListBtn').on('click', function () {
      hideStoryList();
    });

    // 排序按钮
    $('#sortBtn').on('click', function () {
      toggleSortOrder();
    });

    // 关闭剧情详情
    $('#closeDetailBtn').on('click', function () {
      hideStoryDetail();
    });

    // 关闭设置面板
    $('#closeSettingsBtn').on('click', function () {
      hideSettingsPanel();
    });

    // 返回剧情列表（从剧情详情）
    $('#backToMainBtn').on('click', function () {
      hideStoryDetail();
      hideSettingsPanel(); // 关闭设置面板
      showStoryList();
    });

    // 剧情列表项点击 - 直接打开剧情详情
    $(document).on('click', '.story-item', function () {
      try {
        const index = parseInt($(this).data('index'));
        console.log('🎬 点击剧情列表项，索引:', index, '对应剧情:', stories[index]?.title);

        if (isNaN(index) || index < 0 || index >= stories.length) {
          showFeedback(`无效的剧情索引: ${index}`);
          return;
        }

        currentStoryIndex = index;
        updateDisplay();
        hideStoryList();
        hideSettingsPanel(); // 关闭设置面板
        showStoryDetail();
      } catch (error) {
        console.error('剧情列表项点击错误:', error);
        showFeedback(`切换剧情时出错: ${error.message}`);
      }
    });

    // 回到当前剧情按钮
    $('#backToCurrentBtn').on('click', function (e) {
      e.stopPropagation(); // 阻止冒泡到父元素的点击事件
      backToCurrentPlot();
    });

    // 步骤执行按钮点击事件
    $(document).on('click', '.step-execute-btn', function (e) {
      e.stopPropagation(); // 阻止冒泡
      const stepId = $(this).attr('data-step-id'); // 使用attr()获取原始字符串值
      executeStep(stepId);
    });

    // 主题选择器事件监听
    $('#themeSelect').on('change', function () {
      const selectedTheme = $(this).val();
      applyTheme(selectedTheme);
      saveThemeSettings();

      // 根据主题显示不同的反馈消息
      const themeNames = {
        default: '🌅 晨曦蓝调主题',
        dark: '🌌 暗夜星辰主题',
        cute: '🌸 樱花粉梦主题',
        luxury: '✨ 琥珀奢华主题',
      };

      showFeedback(`已切换到 ${themeNames[selectedTheme] || selectedTheme}`);
    });

    // 执行策略选择器事件监听
    $('#executionStrategySelect').on('change', function () {
      const selectedStrategy = $(this).val();
      executionStrategy.mode = selectedStrategy;
      saveExecutionStrategySettings();

      // 根据策略显示不同的反馈消息
      const strategyNames = {
        direct: '⚡ 直接执行',
        copy: '📋 复制到酒馆对话框',
      };

      showFeedback(`已切换到 ${strategyNames[selectedStrategy] || selectedStrategy}`);
    });

    // 还原所有剧情按钮事件监听
    $('#resetAllPlotsBtn').on('click', function () {
      showResetConfirmation();
    });

    // 检测运行环境按钮事件监听
    $('#checkEnvironmentBtn').on('click', function () {
      checkEnvironment(true); // 手动检测，显示提示
    });
  }

  /**
   * 更新显示内容
   */
  function updateDisplay() {
    if (!stories || stories.length === 0) {
      // 显示数据加载失败状态
      showNoPlotState('数据加载中...', '请等待剧情数据加载');
      console.log('📋 显示数据加载状态：stories未准备好');
      return;
    }

    if (currentPlot === '0' || currentPlot === '') {
      // 显示未开始剧情状态 - 当数据源中currentPlot为空时
      showNoPlotState('未选择任何剧情', '点击此处选择剧情开始冒险');
      console.log('🎬 显示未选择剧情状态：currentPlot =', currentPlot);
      return;
    }

    if (currentStoryIndex < 0 || currentStoryIndex >= stories.length) {
      // 显示索引无效状态
      showNoPlotState('剧情索引无效', '请重新选择剧情');
      console.log('⚠️ 显示索引无效状态：currentStoryIndex =', currentStoryIndex);
      return;
    }

    // 恢复正常剧情显示状态
    showNormalPlotState();

    const currentStory = stories[currentStoryIndex];

    // 更新当前剧情信息
    $('#storyTitle').text(currentStory.title); // 新格式不需要移除序号前缀

    // 更新状态显示
    const currentStep = getCurrentStepInfo(currentStory, currentStory.currentStepId);
    const stepStatusIcon = currentStep?.isExecuted ? '✓' : '○';
    const stepStatusColor = currentStep?.isExecuted ? '#34C759' : '#FF9500';
    const stepStatusText = currentStep?.isExecuted ? '已执行' : '未执行';

    const statusHtml = `
      <div style="display: flex; align-items: center; gap: 8px; font-size: 14px;">
        <span style="color: ${stepStatusColor};">${stepStatusIcon} 步骤 ${
      currentStory.currentStepId
    } ${stepStatusText}</span>
        <span style="color: #8E8E93;">|</span>
        <span style="color: #007AFF;">共 ${currentStory.steps?.length || 0} 步</span>
      </div>
    `;
    $('#storyStatus').html(statusHtml);

    // 更新推进剧情显示
    updateProgressDisplay(currentStory);

    // 检查当前显示的剧情是否是数据源中的currentPlot
    const isAtDataSourceCurrentPlot = currentStory.id === currentPlot;
    if (isAtDataSourceCurrentPlot) {
      $('#backToCurrentBtn').hide();
      console.log('当前显示的是数据源currentPlot，隐藏回归按钮');
    } else {
      $('#backToCurrentBtn').show();
      console.log(`当前显示剧情ID ${currentStory.id}，数据源currentPlot是 ${currentPlot}，显示回归按钮`);
    }

    // 更新按钮状态
    updateButtonStates();
  }

  /**
   * 更新按钮状态
   */
  function updateButtonStates() {
    const currentStory = stories[currentStoryIndex];

    if (!currentStory || currentPlot === '0' || currentPlot === '') {
      // 未开始状态，禁用所有导航按钮
      $('#prevBtn').prop('disabled', true);
      $('#nextBtn').prop('disabled', true);
      return;
    }

    // 更新返回上步按钮状态
    const currentStepIdNum = parseInt(currentStepId);
    const canGoBack = currentStepIdNum > 1 || currentStoryIndex > 0;
    $('#prevBtn').prop('disabled', !canGoBack);

    // 更新继续剧情按钮状态
    const nextStep = getNextStep(currentStory);
    const hasNextStep = nextStep !== null;
    const hasNextStory = currentStoryIndex < stories.length - 1;
    const canGoForward = hasNextStep || hasNextStory;
    $('#nextBtn').prop('disabled', !canGoForward);

    // 调试信息
    console.log('🔘 按钮状态更新：', {
      currentPlot: currentPlot,
      currentStepId: currentStepId,
      currentStepIdNum: currentStepIdNum,
      currentStoryIndex: currentStoryIndex,
      canGoBack: canGoBack,
      canGoForward: canGoForward,
      hasNextStep: hasNextStep,
      hasNextStory: hasNextStory,
      prevBtnDisabled: $('#prevBtn').prop('disabled'),
      nextBtnDisabled: $('#nextBtn').prop('disabled'),
    });
  }

  /**
   * 显示未开始剧情状态
   */
  function showNoPlotState(title, hint) {
    console.log('🎭 执行showNoPlotState：', title, hint);

    // 添加特殊样式类
    const $display = $('#currentStoryDisplay');
    $display.addClass('no-plot');
    console.log('添加no-plot样式类到元素：', $display.length > 0 ? '成功' : '失败');

    // 显示图标和文本
    const $icon = $('#noPlotIcon');
    $icon.show();
    console.log('显示noPlotIcon：', $icon.length > 0 ? '成功' : '失败');

    $('#storyTitle').text(title);
    $('#storyStatus').text('');

    // 隐藏回到当前剧情按钮
    $('#backToCurrentBtn').hide();

    // 禁用导航按钮
    $('#prevBtn').prop('disabled', true);
    $('#nextBtn').prop('disabled', true);

    console.log('✅ 未开始剧情状态显示完成：', title);
  }

  /**
   * 恢复正常剧情显示状态
   */
  function showNormalPlotState() {
    console.log('🔄 恢复正常剧情显示状态');

    // 移除特殊样式类
    const $display = $('#currentStoryDisplay');
    $display.removeClass('no-plot');
    console.log('移除no-plot样式类：', $display.hasClass('no-plot') ? '失败' : '成功');

    // 隐藏未开始状态图标
    const $icon = $('#noPlotIcon');
    $icon.hide();
    console.log('隐藏noPlotIcon：', $icon.is(':visible') ? '失败' : '成功');

    console.log('✅ 正常剧情显示状态恢复完成');
  }

  /**
   * 显示/隐藏剧情列表
   */
  function toggleStoryList() {
    const $section = $('#storyListSection');

    if ($section.is(':visible')) {
      hideStoryList();
    } else {
      showStoryList();
    }
  }

  /**
   * 显示剧情列表
   */
  function showStoryList() {
    const $section = $('#storyListSection');
    const $listContainer = $('#storyListContainer');

    // 清空并重新构建列表
    $listContainer.empty();

    stories.forEach((story, index) => {
      // 计算已执行步骤数
      const executedStepsCount = story.steps.filter(step => step.isExecuted).length;
      const totalStepsCount = story.steps.length;
      const isCurrentPlot = String(story.id) === String(currentPlot);

      const $item = $(`
        <div class="story-item ${isCurrentPlot ? 'current' : ''}" data-index="${index}">
          <div class="story-item-content">
            <div class="story-item-title">${story.title}</div>
            <div class="story-item-progress">${executedStepsCount}/${totalStepsCount} 步骤</div>
          </div>
        </div>
      `);
      $listContainer.append($item);
    });

    // 立即显示，无动画
    $section.show().addClass('show').css({
      transition: 'none',
      transform: 'translateY(0) scaleY(1)',
      opacity: '1',
    });

    // 自动滚动到当前剧情（currentPlot.uniqueID）
    setTimeout(() => {
      const currentPlotIndex = stories.findIndex(story => story.id === currentPlot);
      if (currentPlotIndex !== -1) {
        const $currentItem = $listContainer.find(`.story-item[data-index="${currentPlotIndex}"]`);
        if ($currentItem.length > 0) {
          // 使用 scrollIntoView 滚动到当前剧情
          $currentItem[0].scrollIntoView({
            behavior: 'smooth',
            block: 'center',
          });
          console.log('✅ 自动滚动到当前剧情：', stories[currentPlotIndex].title);
        }
      }
    }, 350); // 等待弹出动画完成后再滚动

    // 展开插件
    if (typeof window.expandPlugin === 'function') {
      window.expandPlugin();
    }

    // 额外通知高度变化（确保iframe正确调整）
    setTimeout(() => {
      if (typeof window.notifyParentHeightChange === 'function') {
        window.notifyParentHeightChange();
      }
    }, 100);

    // 再次通知（防止初次计算不准确）
    setTimeout(() => {
      if (typeof window.notifyParentHeightChange === 'function') {
        window.notifyParentHeightChange();
      }
    }, 400);

    // 滚动到顶部
    scrollToTop();
  }

  /**
   * 隐藏剧情列表
   */
  function hideStoryList() {
    const $section = $('#storyListSection');
    $section.removeClass('show');
    setTimeout(() => {
      $section.hide();
    }, 300);

    // 收缩插件
    if (typeof window.collapsePlugin === 'function') {
      window.collapsePlugin();
    }
  }

  /**
   * 切换排序顺序
   */
  function toggleSortOrder() {
    sortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
    sortStories();
    updateSortButton();
    showStoryList(); // 重新显示列表
    showFeedback(`已按序号${sortOrder === 'asc' ? '正向' : '反向'}排序`);
  }

  /**
   * 对剧情进行排序
   */
  function sortStories() {
    const currentStoryId = stories[currentStoryIndex]?.id;

    stories.sort((a, b) => {
      if (sortOrder === 'asc') {
        return a.id - b.id;
      } else {
        return b.id - a.id;
      }
    });

    // 重新找到当前剧情的索引
    if (currentStoryId) {
      const newIndex = stories.findIndex(story => story.id === currentStoryId);
      if (newIndex !== -1) {
        currentStoryIndex = newIndex;
      }
    }

    updateDisplay();
  }

  /**
   * 更新排序按钮显示
   */
  function updateSortButton() {
    const $sortBtn = $('#sortBtn');
    $sortBtn.removeClass('asc desc').addClass(sortOrder);

    if (sortOrder === 'asc') {
      $sortBtn.find('.btn-icon').text('↑');
      $sortBtn.attr('title', '当前正向排序，点击反向排序');
    } else {
      $sortBtn.find('.btn-icon').text('↓');
      $sortBtn.attr('title', '当前反向排序，点击正向排序');
    }
  }

  /**
   * 获取当前步骤信息
   */
  function getCurrentStepInfo(story, stepId) {
    if (!story || !story.steps) return null;
    // 使用 == 进行比较，允许字符串和数字的比较
    return story.steps.find(step => step.stepId == stepId) || story.steps[0];
  }

  /**
   * 更新推进剧情显示
   */
  function updateProgressDisplay(currentStory) {
    const $progressDisplay = $('#storyProgress');

    if (!currentStory || !currentStory.steps) {
      $progressDisplay.hide();
      return;
    }

    // 查找当前剧情的下一个未执行步骤
    const nextStep = getNextStep(currentStory);

    if (nextStep) {
      // 当前剧情还有未执行步骤
      const progressText = `推进剧情: 步骤 ${nextStep.stepId} - ${nextStep.event || '未指定'}`;
      $progressDisplay.text(progressText).show();
    } else {
      // 当前剧情已完成，查找下一个剧情的第一个步骤
      const nextStoryStep = getNextStoryFirstStep();
      if (nextStoryStep) {
        const progressText = `推进剧情: 下一剧情 - ${nextStoryStep.event || '未指定'}`;
        $progressDisplay.text(progressText).show();
      } else {
        // 已经是最后一个剧情且已完成
        $progressDisplay.text('推进剧情: 所有剧情已完成').show();
      }
    }
  }

  /**
   * 获取当前剧情的下一个未执行步骤
   */
  function getNextStep(story) {
    if (!story || !story.steps) return null;

    // 查找第一个未执行的步骤
    return story.steps.find(step => !step.isExecuted);
  }

  /**
   * 获取下一个剧情的第一个步骤
   */
  function getNextStoryFirstStep() {
    if (currentStoryIndex >= stories.length - 1) return null;

    const nextStory = stories[currentStoryIndex + 1];
    if (!nextStory || !nextStory.steps || nextStory.steps.length === 0) return null;

    return nextStory.steps[0];
  }

  /**
   * 处理返回上步操作
   */
  async function handlePreviousStep() {
    const currentStory = stories[currentStoryIndex];
    if (!currentStory) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 使用当前步骤ID进行计算（stepId - 1）
    const currentStepIdNum = parseInt(currentStepId);

    if (currentStepIdNum > 1) {
      // 当前步骤ID大于1，返回到上一个步骤
      const previousStepId = (currentStepIdNum - 1).toString();

      // 检查上一个步骤是否存在（使用 == 允许字符串和数字比较）
      const prevStep = currentStory.steps.find(step => step.stepId == previousStepId);
      if (prevStep) {
        currentStepId = previousStepId;
        currentStory.currentStepId = previousStepId;

        // 在生产环境中保存状态
        await saveCurrentPlotToWorldbook();

        updateDisplay();
        showFeedback(`已返回到步骤 ${previousStepId}`);
      } else {
        showFeedback(`步骤 ${previousStepId} 不存在`);
      }
    } else {
      // 当前步骤ID为1，返回到上一个剧情的最后一个步骤
      if (currentStoryIndex > 0) {
        currentStoryIndex--;
        const prevStory = stories[currentStoryIndex];
        if (prevStory.steps && prevStory.steps.length > 0) {
          // 找到上一个剧情的最后一个步骤
          const lastStep = prevStory.steps[prevStory.steps.length - 1];
          currentPlot = prevStory.id;
          currentStepId = lastStep.stepId;
          prevStory.currentStepId = lastStep.stepId;

          // 在生产环境中保存状态
          await saveCurrentPlotToWorldbook();

          updateDisplay();
          showFeedback(`已返回到上一个剧情的最后步骤：${lastStep.stepId}`);
        } else {
          showFeedback('上一个剧情没有可用步骤');
        }
      } else {
        showFeedback('已经是第一个剧情的第一个步骤了');
      }
    }
  }

  /**
   * 处理继续剧情操作
   */
  async function handleNextStep() {
    const currentStory = stories[currentStoryIndex];
    if (!currentStory) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 查找当前剧情的下一个未执行步骤
    const nextStep = getNextStep(currentStory);

    if (nextStep) {
      // 当前剧情还有未执行步骤，执行该步骤
      executeStep(nextStep.stepId);
    } else {
      // 当前剧情已完成，前进到下一个剧情的第一个步骤
      if (currentStoryIndex < stories.length - 1) {
        currentStoryIndex++;
        const nextStory = stories[currentStoryIndex];
        if (nextStory.steps && nextStory.steps.length > 0) {
          // 更新当前剧情和步骤ID
          currentPlot = nextStory.id;
          currentStepId = nextStory.steps[0].stepId;
          nextStory.currentStepId = nextStory.steps[0].stepId;

          // 自动执行下一个剧情的第一步
          console.log('🎬 自动前进到下一个剧情并执行第一步:', nextStory.title);
          await executeStep(nextStory.steps[0].stepId);

          hideStoryList(); // 关闭剧情列表
        } else {
          showFeedback('下一个剧情没有可用步骤');
        }
      } else {
        showFeedback('已经是最后一个剧情了');
      }
    }
  }

  /**
   * 更新当前剧情ID - 仅用于导航时同步显示
   * 注意：这里只是同步显示，不改变数据源中的currentPlot
   */
  function updateCurrentPlot() {
    // 这个函数仅用于导航时的显示同步，不应该修改原始的currentPlot
    // 原始的currentPlot来自数据源，应该保持不变直到真正执行剧情
    console.log(
      '导航显示更新：当前显示剧情ID',
      stories[currentStoryIndex]?.id,
      '数据源currentPlot:',
      currentPlot,
      'stepId:',
      currentStepId,
    );
  }

  /**
   * 回到数据源中的当前剧情
   */
  function backToCurrentPlot() {
    if (!stories || stories.length === 0) {
      showFeedback('没有可用的剧情数据');
      return;
    }

    if (currentPlot === '0' || currentPlot === '') {
      showFeedback('数据源中未设置当前剧情');
      return;
    }

    // 查找数据源中currentPlot对应的剧情索引
    const targetIndex = stories.findIndex(story => String(story.id) === String(currentPlot));

    if (targetIndex === -1) {
      showFeedback(`找不到剧情ID ${currentPlot}，请检查数据源`);
      console.error(
        '找不到当前剧情：',
        currentPlot,
        '可用剧情：',
        stories.map(s => s.id),
      );
      return;
    }

    // 切换到目标剧情
    const previousIndex = currentStoryIndex;
    currentStoryIndex = targetIndex;
    updateDisplay();

    // 关闭可能打开的面板
    hideStoryList();
    hideSettingsPanel();

    // 打开当前剧情的详情页
    showStoryDetail();

    // 提供详细的反馈信息
    const currentStory = stories[currentStoryIndex];
    showFeedback(`✅ 已回到数据源当前剧情：${currentStory.title}`);
    console.log(`回到当前剧情：从索引 ${previousIndex} 跳转到索引 ${currentStoryIndex}，剧情ID: ${currentPlot}`);
  }

  /**
   * 显示剧情详情页面
   */
  function showStoryDetail() {
    try {
      if (!stories[currentStoryIndex]) {
        console.warn('showStoryDetail: 无效的currentStoryIndex:', currentStoryIndex);
        return;
      }

      const story = stories[currentStoryIndex];
      if (!story) {
        console.warn('showStoryDetail: 无效的故事对象');
        return;
      }

      // 更新剧情基本信息（合并label和值）
      $('#detailTitle').html(`<strong>剧情:</strong> ${story.title || '未指定'}`);
      $('#detailCoreConflict').html(`<strong>摘要:</strong> ${story.summary || '未指定'}`);

      // 检查并处理步骤数组
      if (!story.steps || !Array.isArray(story.steps)) {
        console.warn('showStoryDetail: 故事没有有效的步骤数组:', story);
        $('#stepsList').html('<div class="no-steps">此剧情暂无可用步骤</div>');
      } else {
        // 生成步骤列表
        const stepsHtml = story.steps
          .map(step => {
            if (!step) {
              console.warn('showStoryDetail: 发现无效的步骤对象');
              return '';
            }

            const isExecuted = step.isExecuted;
            const statusClass = isExecuted ? 'executed' : 'pending';
            const buttonText = isExecuted ? '重新执行' : '执行';
            const buttonIcon = isExecuted ? '🔄' : '▶';

            // 处理新格式的characters（对象数组）
            let charactersEditableHtml = '';
            if (step.characters && Array.isArray(step.characters)) {
              charactersEditableHtml = step.characters
                .map((char, charIndex) => {
                  return `
                  <div class="character-item">
                    <div class="char-field">
                      <span class="char-label">角色名:</span>
                      <input type="text" class="char-name-input" 
                             value="${char.name || ''}" 
                             data-step-id="${step.stepId}" 
                             data-char-index="${charIndex}" 
                             data-field="name">
                    </div>
                    <div class="char-field">
                      <span class="char-label">心情:</span>
                      <input type="text" class="char-mood-input" 
                             value="${char.mood || ''}" 
                             data-step-id="${step.stepId}" 
                             data-char-index="${charIndex}" 
                             data-field="mood">
                    </div>
                    <div class="char-field full-width">
                      <span class="char-label">内心:</span>
                      <input type="text" class="char-thoughts-input" 
                             value="${char.innerThoughts || ''}" 
                             data-step-id="${step.stepId}" 
                             data-char-index="${charIndex}" 
                             data-field="innerThoughts">
                    </div>
                  </div>
                `;
                })
                .join('');
            } else {
              charactersEditableHtml = '<div class="no-characters">未指定角色</div>';
            }

            return `
            <div class="step-item ${statusClass}" data-step-id="${step.stepId}">
              <div class="step-header-line">
                <div class="step-id">步骤 ${step.stepId || '未知'}</div>
                <div class="step-location-field">
                  <span class="location-label">📍</span>
                  <input type="text" class="step-location-input" 
                         value="${step.location || ''}" 
                         data-step-id="${step.stepId}">
                </div>
                <button class="step-execute-btn ${statusClass}" data-step-id="${step.stepId || ''}">
                  <span class="btn-icon">${buttonIcon}</span>
                  <span>${buttonText}</span>
                </button>
              </div>
              <div class="step-content">
                <div class="step-field-compact">
                  <span class="inline-label">👥 角色</span>
                  <div class="characters-editor">
