  /**
   * 执行指定步骤
   */
  async function executeStep(stepId) {
    if (!stories[currentStoryIndex]) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 在执行剧情前，先检测运行环境（自动检测，不显示成功消息）
    console.log('🔍 执行前检测运行环境...');
    const envCheckResult = await checkEnvironment(false); // false = 静默模式
    if (envCheckResult === false) {
      // 环境检测失败，已经在checkEnvironment中显示了错误
      return;
    }
    console.log('✅ 运行环境检测通过');

    const currentStory = stories[currentStoryIndex];
    // 使用 == 进行比较，允许字符串和数字的比较
    const targetStep = currentStory.steps.find(step => step.stepId == stepId);

    if (!targetStep) {
      showFeedback(`步骤 ${stepId} 不存在`);
      console.error('找不到步骤:', {
        stepId,
        stepIdType: typeof stepId,
        availableSteps: currentStory.steps.map(s => ({ id: s.stepId, type: typeof s.stepId })),
      });
      return;
    }

    try {
      // 1. 更新本地的currentPlot和stepId
      currentPlot = currentStory.id;
      currentStepId = stepId;

      // 2. 先将 storyTitle 文本设置为执行的 name
      $('#storyTitle').text(currentStory.title);

      // 3. 构建要发送的步骤对象
      const stepObject = buildStepObject(currentStory, targetStep);

      // 4. 拼装要发送的text
      const textToSend = formatStepObjectAsText(stepObject);

      console.log('textToSend======== ', textToSend);

      // 5. 根据执行策略选择调用方式
      if (executionStrategy.mode === 'copy') {
        // 复制到酒馆对话框
        const success = copyToTavernTextarea(textToSend);
        if (success) {
          showFeedback('📋 已复制到酒馆对话框，请手动发送');
        }
      } else {
        // 直接执行（默认）
        triggerQuickReply(textToSend);
      }

      // 6. 标记当前步骤为已执行
      targetStep.isExecuted = true;

      // 7. 更新剧情的执行状态
      currentStory.isExecuted = currentStory.steps.some(step => step.isExecuted);

      // 8. 在生产环境中保存状态到世界书
      await saveCurrentPlotToWorldbook();

      // 9. 更新剧情执行状态到世界书
      await updateStoryExecutionStatus(currentStory);

      // 10. 更新显示
      updateDisplay();

      // 11. 如果详情页面是打开的，重新渲染详情页面以更新按钮状态
      if ($('#storyDetailSection').hasClass('show')) {
        showStoryDetail();
      }

      // 12. 显示执行反馈
      showFeedback(`✅ 已执行 ${currentStory.title} - 步骤${stepId}`);

      console.log('✅ 步骤执行完成：', {
        story: currentStory.title,
        stepId: stepId,
        stepObject: stepObject,
        textSent: textToSend,
      });
    } catch (error) {
      console.error('执行步骤时发生错误:', error);
      showFeedback(`执行步骤时发生错误: ${error.message}`);
    }
  }

  /**
   * 更新剧情执行状态到世界书（新数据格式）
   */
  async function updateStoryExecutionStatus(currentStory) {
    // 只在生产环境中执行
    if (isDev) {
      console.log('🔧 开发环境：跳过剧情状态更新操作');
      return;
    }

    try {
      console.log('📝 生产环境：开始更新剧情执行状态:', currentStory.id);
      console.log('📊 当前剧情状态：', {
        storyId: currentStory.id,
        storyTitle: currentStory.title,
        steps: currentStory.steps.map(s => ({ stepId: s.stepId, isExecuted: s.isExecuted })),
      });

      // 获取世界书名称
      const worldbookName = await getWorldbookName();
      if (!worldbookName) {
        throw new Error('无法获取世界书名称');
      }

      console.log('📚 获取到世界书名称:', worldbookName);

      // 使用updateWorldbookWith更新世界书
      const result = await updateWorldbookWith(worldbookName, worldbook => {
        console.log('📖 世界书条目数量:', worldbook.length);

        let entryFound = false;
        const updatedWorldbook = worldbook.map(entry => {
          if (entry.name.includes('剧情元数据-By萧谴剧情模拟器')) {
            entryFound = true;
            console.log('✅ 找到剧情元数据条目:', entry.name);

            // 检查是否有 [plotResultStart] 标记
            const hasMarkers = entry.content.includes('[plotResultStart]') && entry.content.includes('[plotResultEnd]');
            console.log('📋 数据格式包含标记:', hasMarkers);

            // 提取 JSON 内容
            let jsonContent = entry.content;
            if (hasMarkers) {
              const startMarker = '[plotResultStart]';
              const endMarker = '[plotResultEnd]';
              const startIndex = entry.content.indexOf(startMarker) + startMarker.length;
              const endIndex = entry.content.indexOf(endMarker);
              jsonContent = entry.content.substring(startIndex, endIndex).trim();
              console.log('📋 从标记中提取JSON内容');
            }

            let currentData;
            try {
              currentData = JSON.parse(jsonContent);
            } catch (error) {
              console.error('解析世界书数据失败:', error);
              throw new Error('世界书数据格式错误');
            }

            console.log('📊 原始plotList条目数:', currentData.plotList?.length);

            // 更新plotList中对应剧情的步骤执行状态（只修改isExecuted字段）
            const updatedPlotList = currentData.plotList.map((plot, plotIndex) => {
              // 新格式：使用索引+1作为ID进行比较
              if (plotIndex + 1 === parseInt(currentStory.id)) {
                console.log('🎯 找到需要更新的剧情:', { plotIndex: plotIndex + 1, title: plot.title });

                // 同步当前剧情的步骤执行状态（只修改isExecuted字段）
                const updatedSteps = plot.steps.map(step => {
                  const localStep = currentStory.steps.find(s => s.stepId == step.stepId);
                  if (localStep && localStep.isExecuted) {
                    // 如果本地步骤已执行，设置isExecuted=true
                    console.log(`  ✅ 步骤 ${step.stepId} 标记为已执行`);
                    return { ...step, isExecuted: true };
                  } else if (step.isExecuted) {
                    // 如果步骤原本有isExecuted字段但本地未执行，移除该字段
                    console.log(`  ⚪ 步骤 ${step.stepId} 移除执行标记`);
                    const { isExecuted, ...restStep } = step;
                    return restStep;
                  }
                  // 其他情况保持不变
                  return step;
                });

                return {
                  ...plot,
                  steps: updatedSteps,
                };
              }
              return plot;
            });

            const updatedData = {
              ...currentData,
              plotList: updatedPlotList,
              currentPlot: {
                plotId: parseInt(currentPlot), // 新格式：使用plotId
                stepId: parseInt(currentStepId),
                title: currentData.currentPlot?.title || '剧情元数据-By萧谴剧情模拟器',
              },
            };

            console.log('📝 生产环境：更新后的currentPlot:', updatedData.currentPlot);

            // 格式化 JSON 字符串
            const updatedJsonString = JSON.stringify(updatedData, null, 2);

            // 如果原来有标记，保持标记格式
            const finalContent = hasMarkers
              ? `[plotResultStart]\n${updatedJsonString}\n[plotResultEnd]`
              : updatedJsonString;

            console.log('💾 写入格式:', hasMarkers ? '带标记' : '纯JSON');

            return {
              ...entry,
              content: finalContent,
            };
          }
          return entry;
        });

        if (!entryFound) {
          console.error('❌ 未找到剧情元数据条目');
        }

        return updatedWorldbook;
      });

      console.log('✅ 生产环境：剧情执行状态保存完成', result);
    } catch (error) {
      console.error('❌ 生产环境：更新剧情状态失败:', error);
      console.error('错误堆栈:', error.stack);
      // 不抛出错误，避免影响主流程
    }
  }

