  /**
   * 还原所有剧情
   */
  async function resetAllPlots() {
    try {
      console.log('🔄 开始还原所有剧情...');

      // 重置本地数据
      stories.forEach((story, storyIndex) => {
        if (story.steps && Array.isArray(story.steps)) {
          story.steps.forEach((step, stepIndex) => {
            // 保留第一个剧情的第一步（plotId=1, stepId=1）
            if (story.id === 1 && step.stepId == 1) {
              console.log('⏭️ 保留第一个剧情的第一步: isExecuted=true');
              step.isExecuted = true;
              return;
            }
            // 移除执行标志
            delete step.isExecuted;
          });
          // 更新剧情的执行状态
          story.isExecuted = story.steps.some(step => step.isExecuted);
        }
      });

      // 重置当前剧情为第一个剧情的第一步
      currentPlot = '1';
      currentStepId = '1';
      currentStoryIndex = 0;

      // 在生产环境中更新世界书
      if (!isDev) {
        await resetAllPlotsInWorldbook();
      }

      // 更新显示
      updateDisplay();

      // 如果详情页面打开，重新渲染
      if ($('#storyDetailSection').hasClass('show')) {
        showStoryDetail();
      }

      // 如果列表打开，重新渲染
      if ($('#storyListSection').hasClass('show')) {
        showStoryList();
      }

      showFeedback('✅ 所有剧情已还原成功！');
      console.log('✅ 所有剧情还原完成');
    } catch (error) {
      console.error('❌ 还原剧情失败:', error);
      showFeedback(`还原失败: ${error.message}`);
    }
  }

