   */
  function scrollToTop() {
    try {
      // 检测是否在iframe中
      const isInIframe = window.self !== window.top;

      if (isInIframe) {
        // 生产环境（iframe中）：滚动父页面
        console.log('📜 生产环境：尝试滚动父页面到顶部');
        try {
          // 通知父页面滚动
          window.parent.postMessage(
            {
              type: 'story-assistant-scroll-top',
            },
            '*',
          );
          console.log('✅ 已发送滚动请求到父页面');
        } catch (error) {
          console.warn('⚠️ 无法通知父页面滚动:', error.message);
        }
      } else {
        // 开发环境：直接滚动当前页面
        console.log('📜 开发环境：滚动当前页面到顶部');
        window.scrollTo({
          top: 0,
          behavior: 'smooth',
        });
      }
    } catch (error) {
      console.error('滚动失败:', error);
    }
  }

  /**
   * 检测运行环境（检查并创建必需的世界书条目）
   * @param {boolean} showMessage - 是否显示成功消息（手动检测时为true，自动检测时为false）
   */
  async function checkEnvironment(showMessage = false) {
    // 定义要检查/创建的条目名称
    const REQUIRED_ENTRY_NAME = '剧情执行-By萧谴剧情模拟器';
    // 只在生产环境中执行
    if (isDev) {
      if (showMessage) {
        showFeedback('⚠️ 此功能仅在生产环境（SillyTavern）中可用');
      }
      console.log('⚠️ 开发环境：跳过环境检测');
      return true; // 开发环境直接返回true，不阻止执行
    }

    try {
      console.log('🔍 开始检测运行环境...');
      if (showMessage) {
        showFeedback('🔍 正在检测运行环境...');
      }

      // 1. 获取当前聊天的世界书名称
      const worldbookName = await getWorldbookName();
      if (!worldbookName) {
        throw new Error('无法获取当前世界书名称');
      }

      console.log('📚 当前世界书名称:', worldbookName);

      // 2. 获取世界书内容并检查条目是否已存在
      let hasRequiredEntry = false;

      if (typeof getWorldbook === 'function') {
        const worldbook = await getWorldbook(worldbookName);
        console.log('📖 世界书条目总数:', worldbook?.length || 0);

        // 调试：输出所有条目名称
        if (worldbook && worldbook.length > 0) {
          console.log('📋 世界书中的所有条目名称:');
          worldbook.forEach((entry, index) => {
            console.log(`  [${index + 1}] "${entry.name}" (长度: ${entry.name?.length || 0})`);
          });
          console.log(`🔍 正在查找的条目名称: "${REQUIRED_ENTRY_NAME}" (长度: ${REQUIRED_ENTRY_NAME.length})`);
        }

        // 循环检查是否存在必需的条目
        if (worldbook && worldbook.length > 0) {
          for (const entry of worldbook) {
            // 精确匹配 name 字段
            if (entry.name === REQUIRED_ENTRY_NAME) {
              hasRequiredEntry = true;
              console.log('✅ 找到必需条目:', entry.name);
              console.log('📊 条目详情:', {
                enabled: entry.enabled,
                strategy: entry.strategy?.type,
                position: entry.position?.type,
              });
              break;
            }
          }
        }

        // 如果没找到，输出调试信息
        if (!hasRequiredEntry) {
          console.log('❌ 未找到匹配的条目');
          console.log('💡 可能的原因：');
          console.log('  1. 条目名称不完全匹配（注意空格、大小写、特殊字符）');
          console.log('  2. 条目已被删除或重命名');
          console.log('  3. 条目在其他世界书中');
        }
      } else {
        console.error('❌ getWorldbook 函数不可用');
        throw new Error('getWorldbook 函数不可用');
      }

      // 3. 如果条目已存在，跳过创建
      if (hasRequiredEntry) {
        console.log('✅ 运行环境正常：剧情执行条目已存在，跳过创建');
        if (showMessage) {
          showFeedback('✅ 环境正常：剧情执行条目已存在');
        }
        return true;
      }

      // 4. 如果条目不存在，创建它
      console.log('⚠️ 检测到缺少必需条目，开始创建...');
      if (showMessage) {
        showFeedback('⚠️ 环境有问题：缺少剧情执行条目，正在自动创建...');
      }

      const newEntries = [
        {
          name: REQUIRED_ENTRY_NAME,
          enabled: true,
          strategy: {
            type: 'constant', // 激活策略类型: constant = 蓝灯
            keys: [],
            keys_secondary: { logic: 'and_any', keys: [] },
            scan_depth: 'same_as_global',
          },
          position: {
            type: 'before_character_definition', // 位置类型: 角色定义之前
            role: 'system',
            depth: 4,
            order: 20,
          },
          content:
            '\n# 剧情执行 Rule\nrule:\n  - 判断<user>输入中是否包含${step_data}对象，若存在则激活此条规则，所有剧情创作围绕${step_data}字段展开。\n  - 基于${step_data.location}确定剧情发生场景，若字段值为“未指定场景”，可结合${step_data.event}合理补充基础场景（如街道、车库等），无需过度扩展。\n  - 根据${step_data.characters}组织出场人物：优先使用字段内已定义的角色（按顺序对应`name`“角色1”“角色2”，`mood`“角色1情绪”“角色2情绪”，`innerThoughts`对应内容）；若角色未在既有人物定义中存在，可根据`name`自行创建基础角色，且需保留字段内的`mood`和`innerThoughts`设定。\n  - 以${step_data.event}为核心事件，必须清晰描述“角色1与角色2按事件需求完成关键行动（如交换物品、协作操作等）”的过程，明确人物动作关联，确保事件重点不偏离。\n  - 基于${step_data.development}补充后续：围绕“角色1按发展需求推进后续动作（如调整状态、准备下一步操作等）”展开，仅需体现基础情绪（贴合角色1的`mood`）和简单伏笔（如提及准备补充物品、调整状态等），不延伸无关情节。\n  - [重要!]着重描述人物间的对白和反应：角色1需体现其`mood`对应的个性（如情绪为“果断”则说话简洁、动作利落），角色2需符合其`mood`对应的状态（如情绪为“平静”则回应平淡、配合时无多余情绪），语言、神态、动作需与各自`mood`和`innerThoughts`匹配。\n  - [重要!]若剧情涉及性爱场景，结尾必须处于做爱过程中，采用开放式结尾；若未涉及此类场景，此条不适用。\n  - 若剧情与前文存在轻微逻辑冲突（如场景细节差异），需结合${step_data}字段内容（如用${step_data.location}或${step_data.event}的合理性）进行简单补救，确保逻辑自洽。\n  - 若剧情与前文存在严重逻辑冲突（如${step_data.characters}中的角色已在前文死亡），则丢弃该角色相关的行动描述（如删除角色2参与关键行动的情节），仅保留无冲突角色的剧情线，保证整体合理。',
          probability: 100,
          recursion: {
            prevent_incoming: false,
            prevent_outgoing: false,
            delay_until: null,
          },
          effect: {
            sticky: null,
            cooldown: null,
            delay: null,
          },
        },
      ];

      // 调用 createWorldbookEntries 创建条目
      if (typeof createWorldbookEntries === 'function') {
        const result = await createWorldbookEntries(worldbookName, newEntries);
        console.log('✅ 剧情执行条目创建成功:', result);
        if (showMessage) {
          showFeedback('✅ 已自动创建"剧情执行-By萧谴剧情模拟器"条目，环境修复完成');
